// EXCEDENDO OS REQUISITOS (Demonstrating Creativity & Going Beyond 100%):
// 1. Foi adicionado um campo de contexto emocional/humor do dia (_mood) em cada registro do diário e no salvamento/carregamento de dados.
// 2. Implementada verificação de segurança File.Exists() antes do carregamento de arquivos para evitar travamentos (crashes).
// 3. Foram adicionadas perguntas extras personalizadas no PromptGenerator.

using System;

class Program
{
    static void Main(string[] args)
        {
                Journal journal = new Journal();
                        PromptGenerator promptGenerator = new PromptGenerator();
                                bool running = true;

                                        while (running)
                                                {
                                                            Console.WriteLine("\n--- Menu do Diário ---");
                                                                        Console.WriteLine("1. Escrever um novo registro");
                                                                                    Console.WriteLine("2. Exibir o diário");
                                                                                                Console.WriteLine("3. Carregar o diário de um arquivo");
                                                                                                            Console.WriteLine("4. Salvar o diário em um arquivo");
                                                                                                                        Console.WriteLine("5. Sair");
                                                                                                                                    Console.Write("Escolha uma opção (1-5): ");

                                                                                                                                                string choice = Console.ReadLine();

                                                                                                                                                            switch (choice)
                                                                                                                                                                        {
                                                                                                                                                                                        case "1":
                                                                                                                                                                                                            string prompt = promptGenerator.GetRandomPrompt();
                                                                                                                                                                                                                                Console.WriteLine($"\nPergunta: {prompt}");
                                                                                                                                                                                                                                                    Console.Write("Sua resposta: ");
                                                                                                                                                                                                                                                                        string response = Console.ReadLine();

                                                                                                                                                                                                                                                                                            Console.Write("Como você descreve seu humor/sentimento hoje? ");
                                                                                                                                                                                                                                                                                                                string mood = Console.ReadLine();

                                                                                                                                                                                                                                                                                                                                    string date = DateTime.Now.ToShortDateString();

                                                                                                                                                                                                                                                                                                                                                        Entry newEntry = new Entry();
                                                                                                                                                                                                                                                                                                                                                                            newEntry._date = date;
                                                                                                                                                                                                                                                                                                                                                                                                newEntry._promptText = prompt;
                                                                                                                                                                                                                                                                                                                                                                                                                    newEntry._entryText = response;
                                                                                                                                                                                                                                                                                                                                                                                                                                        newEntry._mood = mood;

                                                                                                                                                                                                                                                                                                                                                                                                                                                            journal.AddEntry(newEntry);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Console.WriteLine("Registro adicionado com sucesso!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    break;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    case "2":
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        journal.DisplayAll();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            break;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            case "3":
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Console.Write("\nDigite o nome do arquivo para carregar (ex: diario.txt): ");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    string loadFileName = Console.ReadLine();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        journal.LoadFromFile(loadFileName);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            break;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            case "4":
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Console.Write("\nDigite o nome do arquivo para salvar (ex: diario.txt): ");
